        c.fillRect(bx, by, bw, bh);
        c.strokeStyle = 'rgba(255,209,0,.9)';
        c.strokeRect(bx, by, bw, bh);
        c.fillStyle = '#FFD100';
        c.textBaseline = 'middle';
        c.fillText(label, bx + fs / 2, by + bh / 2);
